def _cov_query(h, fn, p, cap):
    buf = (ctypes.c_double * cap)()
    n = fn(h, p, buf, cap)
    if n < 0:
        raise AraelError(n, _err(h))
    return buf


def _shape_1(buf):
    return float(buf[0])


def _shape_2(buf):
    return _m.matrix2d.from_elements(buf[0], buf[1], buf[2], buf[3])


def _shape_3(buf):
    return _m.matrix3d.from_elements(*[buf[i] for i in range(9)])


def _shape_n(buf, n):
    return tuple(tuple(buf[r * n + c] for c in range(n)) for r in range(n))


class Covariance:
    """Covariance prepared at the solution; per-entity queries
    (marginal/conditional by param count: 1 -> float, 2/3 ->
    matrix2d/3d, larger -> row-major tuples). Valid until the model is
    dropped or reassembled."""

    __slots__ = ("_h",)

    def __init__(self, h):
        self._h = h

    def marginal(self, e):
        """The entity's marginal covariance block."""
        raise TypeError("no marginal for %r" % (e,))

    def conditional(self, e):
        """Conditional covariance (all other parameters fixed)."""
        raise TypeError("no conditional for %r" % (e,))

    def std_dev(self, e):
        """Per-parameter standard deviations (every CovMode, incl.
        TriDiagonal)."""
        raise TypeError("no std_dev for %r" % (e,))

    def cross(self, a, b):
        """Row-major cross-covariance block between two entities."""
        raise TypeError("no cross-covariance for %r x %r" % (a, b))


class LineObsVec:
    """View of `obs` (vec of Ob); element wrappers re-resolve
    their pointer by key on every access, so growing the collection
    cannot leave them dangling. Mutating while iterating is undefined."""

    __slots__ = ("_p",)

    def __init__(self, p):
        self._p = p

    def __len__(self):
        return _f.line_obs_len(self._p)

    def reserve(self, additional):
        _f.line_obs_reserve(self._p, additional)

    def __getitem__(self, i):
        n = len(self)
        if i < 0:
            i += n
        if not 0 <= i < n:
            raise IndexError(i)
        return Ob(lambda i=i: _f.line_obs_at(self._p, i))

    def __iter__(self):
        for i in range(len(self)):
            yield Ob(lambda i=i: _f.line_obs_at(self._p, i))

    def clear(self):
        _f.line_obs_clear(self._p)

    def truncate(self, n):
        _f.line_obs_truncate(self._p, n)

    def push(self):
        _f.line_obs_push(self._p)
        return self[len(self) - 1]

    def pop(self):
        """Drops the last element; False when already empty."""
        return _f.line_obs_pop(self._p)


class Line:
    """The model. Owns the underlying Rust instance; free() (or GC)
    releases it. One model, one thread."""

    def __init__(self):
        load()
        self._p = _f.line_new()

    def free(self):
        if self._p:
            _f.line_free(self._p)
            self._p = None

    def __del__(self):
        try:
            self.free()
        except Exception:
            pass

    def _solved(self, code, res):
        if code < 0:
            raise AraelError(code, _err(self._p),
                             res if res._detail else None)
        return res

    def solve_dense(self, cfg=None):
        cfg = cfg if cfg is not None else LmConfig()
        r = LmResult()
        return self._solved(
            _f.line_solve_dense(self._p, ctypes.byref(cfg),
                                     ctypes.byref(r)), r)

    def solve_sparse(self, cfg=None, opts=None):
        """Sparse solve; `opts` (a SparseOptions) selects the
        backend's route, None means the defaults."""
        cfg = cfg if cfg is not None else LmConfig()
        r = LmResult()
        return self._solved(
            _f.line_solve_sparse(
                self._p, ctypes.byref(cfg),
                ctypes.byref(opts) if opts is not None else None,
                ctypes.byref(r)), r)

    def solve_band(self, kd, cfg=None):
        """Band Cholesky solve; kd is the half-bandwidth in scalar
        parameters."""
        cfg = cfg if cfg is not None else LmConfig()
        r = LmResult()
        return self._solved(
            _f.line_solve_band(self._p, kd, ctypes.byref(cfg),
                                    ctypes.byref(r)), r)

    def assemble_covariance(self, mode=CovMode.ALL_MARGINALS):
        code = _f.line_assemble_covariance(self._p, int(mode))
        if code != 0:
            raise AraelError(code, _err(self._p))
        return Covariance(self._p)

    def cost(self):
        """Total cost at the current parameter values (no solve)."""
        return _f.line_cost(self._p)

    def validate(self):
        """Empty string when the model is clean, the diagnostic text
        otherwise."""
        return _f.line_validate(self._p).decode()

    def last_error(self):
        return _err(self._p)

    @property
    def k(self):
        return _f.line_k(self._p)

    @k.setter
    def k(self, v):
        _f.line_set_k(self._p, v)

    @property
    def k_optimize(self):
        return _f.line_k_optimize(self._p)

    @k_optimize.setter
    def k_optimize(self, v):
        _f.line_k_set_optimize(self._p, bool(v))

    @property
    def obs(self):
        return LineObsVec(self._p)

